import{_ as t,o as a,c as _,a4 as r}from"./chunks/framework.C85CwpIH.js";const f=JSON.parse('{"title":"湖南江永智能养殖孵出致富蛋 科技赋能乡村振兴","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"湖南江永智能养殖孵出致富蛋 科技赋能乡村振兴","date":"2026-10-27T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202610/t20261023_6488899.htm","summary":"中新网\\n永州10月22日电 (田海忠 陈丽华)每日清晨,湖南省江永县潇浦镇允山社区宇帆家庭农场的智能蛋鸡养殖基地里,生产有条不紊。全自动设备有序完成喂料、温控、集蛋、清粪等作业,新鲜鸡蛋自动传送分拣。\\n养殖场内蛋鸡满笼 　陈丽华 摄\\n这套高效整洁的智慧养殖场景,正是江永现代农业转型升级的生动缩影。...\\n","contentHash":"d40d889c8e22d5a0d8fac04709c27e26","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-10-27-湖南江永智能养殖孵出致富蛋-科技赋能乡村振兴.md","filePath":"news/2026-10-27-湖南江永智能养殖孵出致富蛋-科技赋能乡村振兴.md"}'),n={name:"news/2026-10-27-湖南江永智能养殖孵出致富蛋-科技赋能乡村振兴.md"};function s(o,e,p,l,d,c){return a(),_("div",null,[...e[0]||(e[0]=[r('<h1 id="湖南江永智能养殖孵出致富蛋-科技赋能乡村振兴" tabindex="-1">湖南江永智能养殖孵出致富蛋 科技赋能乡村振兴 <a class="header-anchor" href="#湖南江永智能养殖孵出致富蛋-科技赋能乡村振兴" aria-label="Permalink to &quot;湖南江永智能养殖孵出致富蛋 科技赋能乡村振兴&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202610/t20261023_6488899.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-10-27 摘要: 中新网 永州10月22日电 (田海忠 陈丽华)每日清晨,湖南省江永县潇浦镇允山社区宇帆家庭农场的智能蛋鸡养殖基地里,生产有条不紊。全自动设备有序完成喂料、温控、集蛋、清粪等作业,新鲜鸡蛋自动传送分拣。 养殖场内蛋鸡满笼 　陈丽华 摄 这套高效整洁的智慧养殖场景,正是江永现代农业转型升级的生动缩影。...</p></blockquote><p>这套高效整洁的智慧养殖场景,正是江永现代农业转型升级的生动缩影。近年来,江永县持续推动畜禽养殖向标准化、智能化、生态化转型,积极推广智慧种养模式,依靠科技推动农业提质增效,不断培育壮大绿色富民产业,为乡村产业振兴注入动能。</p><p>该基地配套全套智能养殖系统,能够实时监测、精准调节鸡舍内温湿度、氨氮浓度等环境参数,自动完成喂料、饮水、集蛋、清粪全流程工作。相较于传统人工养殖,智能化模式节约人力、减少疫病发生,从源头稳定禽蛋品质。</p><p>“我们实现全流程自动化养殖,一栋鸡舍只需要两名工人负责日常管护。依托智能管控,蛋鸡约120天便可进入产蛋期,产蛋率稳定维持在95%上下。”宇帆家庭农场负责人周瑞东说,基地坚守生态养殖思路,选用玉米、豆粕等五谷原料科学配比饲喂,产出的鸡蛋风味醇香、品质稳定,主要销往本地及广西市场,同时基地打造种养循环链条,养殖粪污经过无害化处理后制成有机肥,供给周边农田,实现资源化利用、生态双赢。</p><p>周瑞东介绍,目前农场存栏蛋鸡4万羽,布设8条生产线,日产鸡蛋36000枚,年产值800余万元。除此之外,粪污制成的有机肥每年可增收3万余元,淘汰成鸡销售创收约80万元,多元收益进一步夯实养殖效益。</p><p>养殖场外鸡粪有机肥供应农田耕作。陈丽华 摄</p><p>下一步,江永县将继续推广智慧养殖、生态循环农业模式,推动传统种养产业提质升级,持续做强特色富民产业,以科技助力乡村产业高质量发展。(完)</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202610/t20261023_6488899.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',9)])])}const h=t(n,[["render",s]]);export{f as __pageData,h as default};
